import type { PrismEventGameKind } from '@prism/types';
import type { PrismSubmitEventGameActionInput } from '@prism/types';
import type { PrismGameParticipantData, PrismGameParticipantResult, PrismGameSessionResult } from '@prism/types';

export const GAME_RULES = Symbol('GAME_RULES');

export type GameTemplateId = PrismEventGameKind;

export interface GameRuleCurrentRound {
  key: string;
  number: number;
  total: number;
  prompt: string;
  deadlineAt: Date | null;
  /** Sanitized data generated by the server for this credential only. */
  participantData?: PrismGameParticipantData;
  /** Internal host-owned assignment; never included in a participant read model. */
  teamAssignment?: { teamId: string; teamLabel: string };
}

export interface GameRuleScoreResult {
  points: number;
  isCorrect: boolean;
  result?: PrismGameParticipantResult | PrismGameSessionResult;
}

export interface GameRuleDefinition {
  templateId: GameTemplateId;
  validateConfiguration(configuration: Readonly<Record<string, unknown>>): string[];
  getCurrentRound(input: {
    configuration: Readonly<Record<string, unknown>>;
    startedAt: Date;
    now: Date;
    participantKey?: string;
    teamId?: string | null;
    teamLabel?: string | null;
  }): GameRuleCurrentRound | null;
  validateSubmission(input: {
    configuration: Readonly<Record<string, unknown>>;
    currentRound: GameRuleCurrentRound;
    action: PrismSubmitEventGameActionInput;
  }): string[];
  scoreSubmission(input: {
    configuration: Readonly<Record<string, unknown>>;
    submission: Readonly<Record<string, unknown>>;
    currentRound?: GameRuleCurrentRound;
    submittedAt?: Date;
  }): GameRuleScoreResult;
}

export interface GameRuleRegistryPort {
  get(templateId: GameTemplateId): GameRuleDefinition | undefined;
  register(definition: GameRuleDefinition): void;
}
